def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    desperate_count = 0
    rich_aggressive = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 2:
                desperate_count += 1
            if opp.get('budget', 0) > 500:
                prev = opp.get('previous_trace', {}) or {}
                pb = prev.get('bid')
                if pb is not None and pb >= 70:
                    rich_aggressive += 1
            prev = opp.get('previous_trace', {}) or {}
            pb = prev.get('bid')
            if pb is not None:
                prev_bids.append(float(pb))

    if not alive:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    total_alive = len(alive) + 1
    pressure = supply / float(total_alive * WATER_REQ)

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 1

    if supply <= 16:
        urgency += 2
    elif supply <= 18:
        urgency += 1

    if day >= 8:
        urgency += 1

    if pressure >= 0.45 and urgency <= 1:
        bid = 14.0
    elif pressure >= 0.35 and urgency <= 2:
        bid = 22.0
    else:
        if urgency >= 5:
            bid = max(72.0, highest_prev + 2.0)
        elif urgency >= 3:
            bid = max(48.0, min(78.0, highest_prev * 0.82 + 3.0))
        else:
            bid = max(28.0, min(58.0, avg_prev * 0.72 + 2.0))

    if rich_aggressive >= 2 and urgency <= 2:
        bid = min(bid, 24.0)

    if desperate_count >= 2 and urgency >= 3:
        bid = max(bid, highest_prev + 3.0)

    if hp <= 1 or no_water_days >= 3:
        bid = max(bid, 90.0)

    reserve = 0.0
    if day <= 7:
        reserve = 25.0
    elif day <= 9:
        reserve = 10.0

    bid = min(bid, budget)
    if budget > reserve:
        bid = min(bid, budget - reserve + min(reserve, 5.0))

    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return float(min(my_status['budget'], 10.0))

    prev_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and 'bid' in prev:
            prev_bids.append(prev['bid'])

    if prev_bids:
        avg_prev = sum(prev_bids) / len(prev_bids)
        bid = avg_prev * 1.05
    else:
        bid = DAILY_SALARY * 0.6

    if my_status['hp'] < 4:
        bid = max(bid, DAILY_SALARY * 0.9)

    return float(min(my_status['budget'], bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    alive_opponents = [o for o in opponents_status.values() if o.get('alive')]
    # Collect yesterday's bids from alive opponents' traces
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(float(prev['bid']))
    # Our health assessment
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']
    # Determine bid
    if hp <= 3 or no_water_days >= 1:
        # Need water urgently
        if yesterday_bids:
            target = max(yesterday_bids) + 2.0
        else:
            target = DAILY_SALARY * 0.85
        return min(budget, max(target, DAILY_SALARY * 0.5))
    else:
        # Healthy, try to save
        if yesterday_bids:
            highest_prev = max(yesterday_bids)
            if highest_prev > DAILY_SALARY * 0.7:
                # Opponents aggressive, we can try low if we are healthy
                return min(budget, max(DAILY_SALARY * 0.3, highest_prev * 0.6))
            else:
                return min(budget, max(DAILY_SALARY * 0.4, highest_prev + 1.5))
        else:
            return min(budget, DAILY_SALARY * 0.5)
